/*************************************************************************************************\
 ***  FUNCTION:
 ***      A_SWA_Runnable
 ***
 ***  DESCRIPTION:
 ***
 ***  PARAMETERS:
 ***      Type               Name                Description
 ***      ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ 
 ***
 ***  RETURNS:
 ***      void
 ***
 ***  SETTINGS:
 ***
\*************************************************************************************************/
void A_SWA_Runnable(void)
{
   {
      IDT E1 = Rte_InitValue_PPort_E1;

      /* Performs an "implicit" write on a sender-receiver communication data with "data" semantics
      */
      Rte_IWrite_SWA_Runnable_PPort_E1(E1);
   }
   {
      IDT * pE1;
      IDT E1 = Rte_InitValue_PPort_E1;

      /* Performs an implicit write on a sender-receiver communication data item with data semantics
      . */
      pE1 = Rte_IWriteRef_SWA_Runnable_PPort_E1();
      *pE1 = E1;
   }
   {
      IDT E1 = Rte_InitValue_PPort1_E1;

      /* Performs an "implicit" write on a sender-receiver communication data with "data" semantics
      */
      Rte_IWrite_SWA_Runnable_PPort1_E1(E1);
   }
   {
      IDT * pE1;
      IDT E1 = Rte_InitValue_PPort1_E1;

      /* Performs an implicit write on a sender-receiver communication data item with data semantics
      . */
      pE1 = Rte_IWriteRef_SWA_Runnable_PPort1_E1();
      *pE1 = E1;
   }
}

